class Solution:
    def maxProduct(self, root) -> int:
        MOD = 10**9 + 7
        subtree_sums = []

        def dfs(node):
            if not node:
                return 0
            s = node.val + dfs(node.left) + dfs(node.right)
            subtree_sums.append(s)
            return s

        total = dfs(root)
        max_prod = 0
        for s in subtree_sums:
            max_prod = max(max_prod, s * (total - s))
        return max_prod % MOD

